 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The canvas has a two-cell background margin, then a one-cell frame,
    # followed by a diagonally repeating colored field.
    diagonal_colors = {}
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v != 0:
                diagonal_colors.setdefault(r + c, Counter())[v] += 1

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                counts = diagonal_colors.get(r + c)
                if not counts:
                    raise ValueError(f'No observed color for diagonal {r+c}')
                out[r][c] = counts.most_common(1)[0][0]
    return out
