    """Restore erased cells in a framed, row-wise periodic color field."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4

    # Each horizontal row of the colored field has its own repeating cycle;
    # the left edge can contain a short irregular seed, so infer the cycle
    # from the longest consistent observed suffix of that row.
    for r in range(3, h):
        known = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        if not any(grid[r][c] == 0 for c in range(3, w)):
            continue
        candidates = []
        for start in range(3, w):
            suffix = [(c, v) for c, v in known if c >= start]
            if len(suffix) < 6:
                continue
            for period in range(1, min(10, w - start) + 1):
                values = {}
                consistent = True
                for c, v in suffix:
                    phase = (c - start) % period
                    if phase in values and values[phase] != v:
                        consistent = False
                        break
                    values[phase] = v
                if consistent:
                    candidates.append((start, period, values, len(suffix)))
                    break
        if not candidates:
            # Fallback for a very large erased region: use the shortest
            # consistent cycle supported by all visible cells in the row.
            for period in range(1, min(10, w - 3) + 1):
                values = {}
                consistent = True
                for c, v in known:
                    phase = (c - 3) % period
                    if phase in values and values[phase] != v:
                        consistent = False
                        break
                    values[phase] = v
                if consistent:
                    candidates.append((3, period, values, len(known)))
                    break
        if not candidates:
            raise ValueError(f"Cannot infer row pattern {r}")

        # Earliest supported suffix gives the largest extent; among equally
        # early candidates, choose the simplest cycle.
        start, period, values, _ = min(candidates, key=lambda item: (item[0], item[1]))
        for c in range(3, w):
            if grid[r][c] == 0:
                phase = (c - start) % period
                if phase not in values:
                    raise ValueError(f"Unobserved cycle phase in row {r}")
                out[r][c] = values[phase]
    return out
