 "content": "def transform(grid):
    """Restore missing cells in the framed, horizontally periodic pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Restore the outer background and the solid frame.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r < 2 or c < 2):
                out[r][c] = 1
            elif grid[r][c] == 0 and (r == 2 or c == 2):
                out[r][c] = 4

    # Colored rows contain an initial seed, then a repeating sequence.
    # Infer the smallest supported period from intact cells, allowing the
    # seed to be irregular and erased blocks to interrupt observed values.
    for r in range(3, h):
        known = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        holes = [c for c in range(3, w) if grid[r][c] == 0]
        if not holes:
            continue

        candidates = []
        for start in range(3, w):
            suffix = [(c, v) for c, v in known if c >= start]
            for period in range(1, min(10, w) + 1):
                if len(suffix) < 2 * period:
                    continue
                phases = {}
                valid = True
                for c, v in suffix:
                    k = c % period
                    if k in phases and phases[k] != v:
                        valid = False
                        break
                    phases[k] = v
                if valid and len(phases) == period:
                    candidates.append((start, period, phases))
        if not candidates:
            raise ValueError(f"Cannot infer repeating pattern in row {r}")

        # Start as early as the evidence supports, then prefer the shortest
        # consistent cycle. Phase keys use absolute columns, so extension in
        # either direction stays aligned with the visible pattern.
        start, period, phases = min(candidates, key=lambda x: (x[0], x[1]))
        for c in holes:
            out[r][c] = phases[c % period]

    return out
